{
  "info": {
    "title": "UAE Authorization Endpoints API",
    "description": "## UAE Open Finance Authorization Endpoints Specification\n\nThis API description provides the API descriptions for two OAuth 2.0 operations included in the FAPI 2.0 Security Profile:\n\n* [Pushed Authorization Requests](https://datatracker.ietf.org/doc/html/rfc9126), which implement [Rich Authorization Requests](https://datatracker.ietf.org/doc/html/rfc9396) (RAR) payloads to provide Consent for a given use case.\n\n* Token operations that provide details of the RAR associated with a given Access Token request.\n\nPlease note that the Authorization Request is provided as a plain JSON object, which only describes the payload of a signed JSON Web Token (JWS).\n\nUsers of this API description must ensure they implement the Authorization Request as a JWS, encoding the payload as described by [RFC 7515](https://datatracker.ietf.org/doc/html/rfc7515) and reflecting the requirements of the API Security Profile for the UAE Open Finance Framework.",
    "version": "v2.1-errata3"
  },
  "servers": [
    {
      "url": "https://as1.[LFICODE].apihub.openfinance.ae"
    },
    {
      "url": "https://as1.[LFICODE].preprod.apihub.openfinance.ae"
    },
    {
      "url": "https://as1.[LFICODE].sandbox.apihub.openfinance.ae"
    }
  ],
  "source_path": "/par",
  "operations": {
    "post": {
      "operationId": "CreatePushedAuthorizationRequestV21",
      "summary": "Pushed Authorization Request endpoint",
      "description": "Submit a Rich Authorization Request (RAR) to the Pushed Authorization Request (PAR) Endpoint, as defined in [RFC 9126](https://datatracker.ietf.org/doc/html/rfc9126).\n\nThe `application/json` Content Type is included in the Request Body for tooling compatibility, but requests **MUST** be sent using the Content Type `application/x-www-form-urlencoded`.",
      "parameters": [],
      "responses": {
        "200": {
          "description": "The request has succeeded.",
          "content": {
            "application/json": {
              "schema": {
                "$ref": "#/components/schemas/AEPushedAuthorizationRequests.AEPushedAuthorizationResponseBody"
              }
            }
          }
        },
        "400": {
          "description": "Bad Request",
          "content": {
            "application/json": {
              "schema": {
                "$ref": "#/components/schemas/OAuthBadRequestErrorResponse"
              }
            }
          }
        },
        "405": {
          "description": "Method Not Allowed"
        },
        "413": {
          "description": "Content Too Large"
        },
        "429": {
          "description": "Too Many Requests",
          "headers": {
            "retry-after": {
              "required": true,
              "description": "Number in seconds to wait",
              "schema": {
                "type": "integer",
                "format": "int64"
              }
            }
          }
        }
      },
      "tags": [
        "Pushed Authorization Requests"
      ],
      "requestBody": {
        "required": true,
        "content": {
          "application/json": {
            "schema": {
              "$ref": "#/components/schemas/AEPushedAuthorizationRequestsV21.PushedAuthorizationRequestBody"
            }
          },
          "application/x-www-form-urlencoded": {
            "schema": {
              "$ref": "#/components/schemas/AEPushedAuthorizationRequestsV21.PushedAuthorizationRequestBody"
            }
          }
        }
      }
    }
  }
}

{
  "type": "object",
  "required": [
    "request_uri",
    "expires_in"
  ],
  "properties": {
    "request_uri": {
      "type": "string",
      "description": "The request URI corresponding to the authorization request posted"
    },
    "expires_in": {
      "type": "integer",
      "description": "A JSON number that represents the lifetime of the request URI in seconds as a positive integer"
    }
  },
  "additionalProperties": false
}

{
  "type": "object",
  "allOf": [
    {
      "$ref": "#/components/schemas/OAuthErrorResponse"
    }
  ],
  "description": "Bad Request",
  "additionalProperties": false
}

{
  "type": "object",
  "required": [
    "error"
  ],
  "properties": {
    "error": {
      "$ref": "#/components/schemas/OAuthErrorCodes"
    },
    "error_description": {
      "type": "string",
      "description": "Description of the error providing additional information"
    },
    "error_uri": {
      "type": "string",
      "description": "A URI identifying a human-readable web page with information about the error"
    }
  },
  "description": "Error returned from endpoints compliant with security profile",
  "additionalProperties": false
}

{
  "type": "object",
  "required": [
    "client_assertion_type",
    "client_assertion",
    "request"
  ],
  "properties": {
    "client_assertion_type": {
      "type": "string",
      "enum": [
        "urn%3Aietf%3Aparams%3Aoauth%3Aclient-assertion-type%3Ajwt-bearer"
      ],
      "description": "Client Assertion using JWT Authentication, as described by [RFC 7523](https://datatracker.ietf.org/doc/html/rfc7523#section-2.2)"
    },
    "client_assertion": {
      "type": "string",
      "description": "private_key_jwt client assertion"
    },
    "request": {
      "type": "object",
      "properties": {
        "authorization_details": {
          "type": "array",
          "items": {
            "$ref": "#/components/schemas/AEPushedAuthorizationRequestsV21.AEPushedAuthorizationRequestAuthorizationDetailTypes"
          },
          "minItems": 1,
          "maxItems": 1
        },
        "iss": {
          "type": "string",
          "description": "The Issuer claim for the JWT, as described in [RFC 7519](https://tools.ietf.org/html/rfc7519#section-4.1.1)"
        },
        "aud": {
          "type": "string",
          "description": "The Audience claim for the JWT, as described in [RFC 7519](https://tools.ietf.org/html/rfc7519#section-4.1.3)\n\nThis value is constrained to a single `string` value, as prescribed by [FAPI 2.0 Security Profile](https://openid.net/specs/fapi-2_0-security-profile-ID2.html#section-5.3.2.1-2.5.1)."
        },
        "exp": {
          "type": "number",
          "description": "The Expiration Time claim for the JWT, as described in [RFC 7519](https://tools.ietf.org/html/rfc7519#section-4.1.4)"
        },
        "nbf": {
          "type": "number",
          "description": "The Not Before claim for the JWT, as described in [RFC 7519](https://www.rfc-editor.org/rfc/rfc7519#section-4.1.5) and expanded in the FAPI 2.0 Security Profile."
        },
        "client_id": {
          "type": "string",
          "description": "The OAuth 2.0 Client ID of the Client, as set in the Open Finance Trust Framework (OFTF)."
        },
        "response_type": {
          "type": "string",
          "enum": [
            "code"
          ],
          "description": "The OAuth 2.0 response type requested by the Client. This defaults to 'code', as per the FAPI 2.0 Security Profile, as only Authorization Code Flow is supported."
        },
        "redirect_uri": {
          "type": "string",
          "format": "uri",
          "description": "The OAuth 2.0 redirect URI of the Client, as set in the Open Finance Trust Framework. This **MUST** match a redirect URI value registered at the OFTF."
        },
        "scope": {
          "type": "string",
          "description": "The OAuth 2.0 scope requested by the Client. This **MUST** match one-or-more scope values provided in the API descriptions for the Open Finance Standards."
        },
        "state": {
          "type": "string",
          "description": "The OAuth 2.0 state value requested by the Client, as described in [RFC 6749](https://tools.ietf.org/html/rfc6749#section-4.1.1)."
        },
        "nonce": {
          "type": "string",
          "description": "Nonce value as described in [OpenID Connect Core](https://openid.net/specs/openid-connect-core-1_0.html) and expanded in the FAPI 2.0 Security Profile."
        },
        "max_age": {
          "type": "integer",
          "description": "Maximum Authentication Age as described in [OpenID Connect Core](https://openid.net/specs/openid-connect-core-1_0.html)."
        },
        "login_hint": {
          "oneOf": [
            {
              "type": "string"
            },
            {
              "$ref": "#/components/schemas/AESecurityProfile.AELoginHintJwePayload"
            }
          ],
          "description": "Optional parameter that can be used to send the User's Emirates ID or Trade\nLicense Number as an encrypted JSON Web Token (JWE). This mechanism is\nprovided to allow LFIs to correlate the User identity, and therefore the\nfeatures of their account, prior to the User being redirected to the LFI's\nauthentication page.\n\nThe value **MUST** be a JWE, encrypted with the target LFI's public key\nwith the User identifier set as the JWE. The payload MUST be a JSON object\ncreated based on the Schema Object `AELoginHintJwePayload`. This JSON\nobject will form the basis of the data contained in the JWE, and should\nbe signed with the TPP signing key to create a JSON Web Signature.\n\nPlease note that, as per OpenID Connect Core, `login_hint` is used for\ndiscovery and is supported to provide hints to the LFI on the User\nidentity and therefore the data or services supported at the LFI.\n`login_hint` **MUST NOT** be used to bypass authentication of the User, nor\nshould a request be rejected if `login_hint` is not provided.\n\nThe `type` value of the `login_hint` property is shown as a `string` due\nto the limitations of the OpenAPI specification in cross-referencing a\nSchema Object that is also a JSON Web Token, as there is no deterministic\nmechanism to display the underlying structure of the JWE payload.\nThis property is therefore represented in both encoded and decoded\nform in the API description using a `oneOf`, to help implementers readily\nunderstand both the structure and serialized form of the property.\n\n**Please ensure your implementation reflects the AELoginHintJwePayload Schema**\n**Object structure and any notes provided on implementing a JWS and JWE**"
        },
        "code_challenge": {
          "type": "string",
          "description": "Code challenge as described in [RFC 7636](https://www.rfc-editor.org/rfc/rfc7636.html#section-4.3), which implements the Proof Key for Code Exchange (PKCE) extension to OAuth 2.0. PKCE is mandated by the FAPI 2.0 Security Profile."
        },
        "code_challenge_method": {
          "type": "string",
          "enum": [
            "S256"
          ],
          "description": "Code challenge method as described in [RFC 7636](https://www.rfc-editor.org/rfc/rfc7636.html#section-4.3), which implements the Proof Key for Code Exchange (PKCE) extension to OAuth 2.0. PKCE is mandated by the FAPI 2.0 Security Profile, which prescribes the use of the `S256` method."
        }
      },
      "required": [
        "authorization_details",
        "iss",
        "exp",
        "nbf",
        "client_id",
        "response_type",
        "redirect_uri",
        "scope",
        "code_challenge",
        "code_challenge_method"
      ],
      "description": "Authorization Request for a Rich Authorization Request (RAR) objects that encapsulate the consent agreed between the TPP and the User.\n\nOnly a single RAR may be submitted at v2.1 of the Open Finance Standards.      \n\nThis object defines the required JSON Web Token (JWT) payload. This **does not** represent a correctly serialized JWT, but provides a Schema Object that correctly defines the supported RARs.\n",
      "additionalProperties": false
    }
  },
  "additionalProperties": false
}

{
  "anyOf": [
    {
      "$ref": "#/components/schemas/AEBankDataSharingRichAuthorizationRequestsV21.AEBankDataSharingAuthorizationDetailsProperties"
    },
    {
      "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequestsV21.AEBankServiceInitiationAuthorizationDetailsProperties"
    },
    {
      "$ref": "#/components/schemas/AEInsuranceDataSharingRichAuthorizationRequestsV21.AEInsuranceDataSharingAuthorizationDetailsProperties"
    }
  ]
}

{
  "type": "object",
  "required": [
    "type",
    "consent"
  ],
  "properties": {
    "type": {
      "type": "string",
      "enum": [
        "urn:openfinanceuae:account-access-consent:v2.1"
      ],
      "description": "The Rich Authorization Request type, as defined by [RFC 9396](https://datatracker.ietf.org/doc/html/rfc9396#section-2-2.2)."
    },
    "consent": {
      "type": "object",
      "properties": {
        "ConsentId": {
          "$ref": "#/components/schemas/AEConsentId"
        },
        "BaseConsentId": {
          "$ref": "#/components/schemas/AEBaseConsentId"
        },
        "Permissions": {
          "type": "array",
          "items": {
            "$ref": "#/components/schemas/AEBankDataSharingRichAuthorizationRequests.AEBankDataSharingConsentPermissionCodes"
          },
          "minItems": 1
        },
        "ExpirationDateTime": {
          "$ref": "#/components/schemas/AEPushedAuthorizationRequests.AEConsentExpirationDateTime"
        },
        "FromDate": {
          "$ref": "#/components/schemas/AEBankDataSharingRichAuthorizationRequests.AEBankDataSharingFromDate"
        },
        "ToDate": {
          "$ref": "#/components/schemas/AEBankDataSharingRichAuthorizationRequests.AEBankDataSharingToDate"
        },
        "AccountType": {
          "type": "array",
          "items": {
            "$ref": "#/components/schemas/AEBankDataSharing.AEExternalAccountTypeCode"
          }
        },
        "AccountSubType": {
          "type": "array",
          "items": {
            "$ref": "#/components/schemas/AEBankDataSharing.AEExternalAccountSubTypeCode"
          },
          "description": "Account Sub Types permitted under the consent."
        },
        "OnBehalfOf": {
          "$ref": "#/components/schemas/AEBankDataSharingRichAuthorizationRequests.OnBehalfOf"
        },
        "OpenFinanceBilling": {
          "$ref": "#/components/schemas/AEBankDataSharingRichAuthorizationRequestsV21.AEBankDataSharingOpenFinanceBilling"
        }
      },
      "required": [
        "ConsentId",
        "Permissions",
        "ExpirationDateTime",
        "OpenFinanceBilling"
      ],
      "description": "Properties of the consent agreed by the User with the TPP.",
      "additionalProperties": false
    },
    "subscription": {
      "type": "object",
      "properties": {
        "Webhook": {
          "type": "object",
          "properties": {
            "Url": {
              "type": "string",
              "description": "The TPP Callback URL being registered with the LFI"
            },
            "IsActive": {
              "type": "boolean",
              "description": "The TPP specifying whether the LFI should send (IsActive true) or not send (IsActive false) Webhook Notifications to the TPP's Webhook URL"
            }
          },
          "required": [
            "Url",
            "IsActive"
          ],
          "description": "Properties of the TPP Webhook and the state of the subscription.",
          "additionalProperties": false
        }
      },
      "required": [
        "Webhook"
      ],
      "description": "Optional subscription to Event Notifications, to be sent to the TPP Webhook registered at the API Hub.",
      "additionalProperties": false
    }
  },
  "description": "Properties for creating a consent object for the first time a User consents to TPP access to account information data",
  "additionalProperties": false,
  "title": "Bank Data Sharing Consent"
}

{
  "type": "string",
  "format": "date-time",
  "description": "Specified date and time the consent will expire.\n\nAll dates in the JSON payloads are represented in ISO 8601 date-time format.\n\nAll date-time fields in responses must include the timezone, for example: 2023-04-05T10:43:07+00:00"
}

{
  "type": "string",
  "format": "date",
  "description": "Specified start date for the transaction or statement query period.\n\nIf this is not populated, the start date will be open ended, and data will be returned from the earliest available transaction or statement.\n\nAll dates in the JSON payloads are represented in ISO 8601 date format.  For example: 2025-01-01"
}

{
  "type": "string",
  "format": "date",
  "description": "Specified end date for the transaction or statement query period.\n\nIf this is not populated, the end date will be open ended, and data will be returned to the latest available transaction or the last statement generated.\n\nAll dates in the JSON payloads are represented in ISO 8601 date format.  For example: 2025-12-31    "
}

{
  "type": "string",
  "enum": [
    "Retail",
    "SME",
    "Corporate"
  ],
  "description": "Specifies the type of account (Retail, SME or Corporate)."
}

{
  "type": "object",
  "properties": {
    "TradingName": {
      "type": "string",
      "description": "Trading Name"
    },
    "LegalName": {
      "type": "string",
      "description": "Legal Name"
    },
    "IdentifierType": {
      "type": "string",
      "enum": [
        "Other"
      ],
      "description": "Identifier Type"
    },
    "Identifier": {
      "type": "string",
      "description": "Identifier"
    }
  },
  "description": "On Behalf Of",
  "additionalProperties": false
}

{
  "type": "object",
  "required": [
    "UserType",
    "Purpose"
  ],
  "properties": {
    "UserType": {
      "type": "string",
      "enum": [
        "Retail",
        "SME",
        "Corporate"
      ],
      "description": "Type of User."
    },
    "Purpose": {
      "type": "string",
      "enum": [
        "AccountAggregation",
        "RiskAssessment",
        "TaxFiling",
        "Onboarding",
        "Verification",
        "QuoteComparison",
        "BudgetingAnalysis",
        "FinancialAdvice",
        "AuditReconciliation"
      ],
      "description": "Purpose of data sharing request."
    }
  },
  "description": "Billing parameters specified by the TPP.",
  "additionalProperties": false
}

{
  "type": "object",
  "required": [
    "type",
    "consent"
  ],
  "properties": {
    "type": {
      "type": "string",
      "enum": [
        "urn:openfinanceuae:service-initiation-consent:v2.1"
      ],
      "description": "The Rich Authorization Request type, as defined by [RFC 9396](https://datatracker.ietf.org/doc/html/rfc9396#section-2-2.2)."
    },
    "consent": {
      "allOf": [
        {
          "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequestsV21.AEBankServiceInitiationConsentProperties"
        }
      ],
      "description": "Properties of the consent agreed by the User with the TPP."
    },
    "subscription": {
      "type": "object",
      "properties": {
        "Webhook": {
          "type": "object",
          "properties": {
            "Url": {
              "type": "string",
              "description": "The TPP Callback URL being registered with the LFI"
            },
            "IsActive": {
              "type": "boolean",
              "description": "The TPP specifying whether the LFI should send (IsActive true) or not send (IsActive false) Webhook Notifications to the TPP's Webhook URL"
            }
          },
          "required": [
            "Url",
            "IsActive"
          ],
          "description": "Properties of the TPP Webhook and the state of the subscription.",
          "additionalProperties": false
        }
      },
      "required": [
        "Webhook"
      ],
      "description": "Optional subscription to Event Notifications, to be sent to the TPP Webhook registered at the API Hub.",
      "additionalProperties": false
    }
  },
  "description": "A Rich Authorization Request object for a Bank Service Initiation Consent.",
  "additionalProperties": false,
  "title": "Bank Service Initiation Consent"
}

{
  "type": "object",
  "required": [
    "PersonalIdentifiableInformation",
    "ControlParameters",
    "ConsentId",
    "ExpirationDateTime",
    "PaymentPurposeCode"
  ],
  "properties": {
    "PersonalIdentifiableInformation": {
      "anyOf": [
        {
          "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequests.AEDomesticPaymentPII"
        },
        {
          "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequests.AEInternationalPaymentPII"
        },
        {
          "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequests.AEJWEPaymentPII"
        }
      ],
      "description": "Personal Identifiable Information, represented in both encoded and decoded form using a `oneOf`.\n\nImplementers **MUST** adhere to the Schema Object provided in `AEPaymentPII` when creating the object to be signed and encrypted through a JWS and JWE.\n\nDebtor and Creditor information **MUST** be set according to the rules for the payment type being instructed.\n\nThe encrypted form of the object is provided by the `AEJWEPaymentPII` Schema Object, which **MUST** be used when invoking the PAR operation."
    },
    "ControlParameters": {
      "allOf": [
        {
          "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequestsV21.AEBankServiceInitiationControlParametersProperties"
        }
      ],
      "description": "Control Parameters set the overall rules for the Payment Schedule."
    },
    "ConsentId": {
      "$ref": "#/components/schemas/AEConsentId"
    },
    "BaseConsentId": {
      "$ref": "#/components/schemas/AEBaseConsentId"
    },
    "IsSingleAuthorization": {
      "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequests.IsSingleAuthorization"
    },
    "AuthorizationExpirationDateTime": {
      "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequests.AuthorizationExpirationDateTime"
    },
    "ExpirationDateTime": {
      "type": "string",
      "format": "date-time",
      "description": "Specified date and time the consent will expire.\n\nAll dates in the JSON payloads are represented in ISO 8601 date-time format.\nAll date-time fields in responses must include the timezone. An example is :2023-04-05T10:43:07+00:00"
    },
    "Permissions": {
      "type": "array",
      "items": {
        "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequests.AEBankServiceInitiationConsentPermissionCodes"
      },
      "description": "Specifies the permitted Bank Data Sharing permissions, which is the data clusters being consented by the User, and requested for authorization with the LFI. Allows TPPs to check the User balance at the payment account."
    },
    "CurrencyRequest": {
      "allOf": [
        {
          "$ref": "#/components/schemas/AEBankServiceInitiation.AECurrencyRequest"
        }
      ],
      "description": "Currency request "
    },
    "DebtorReference": {
      "$ref": "#/components/schemas/AEBankServiceInitiation.AEDebtorReference"
    },
    "CreditorReference": {
      "$ref": "#/components/schemas/AEBankServiceInitiation.AECreditorReference"
    },
    "PaymentPurposeCode": {
      "$ref": "#/components/schemas/AEBankServiceInitiation.AEPaymentPurposeCode"
    },
    "SponsoredTPPInformation": {
      "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequests.AEBankServiceInitiationSponsoredTPPInformation"
    }
  },
  "additionalProperties": false
}

{
  "type": "object",
  "properties": {
    "Initiation": {
      "type": "object",
      "properties": {
        "DebtorAccount": {
          "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequests.AEBankServiceInitiationDebtorAccountProperties"
        },
        "Creditor": {
          "type": "array",
          "items": {
            "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequests.AEDomesticCreditor"
          },
          "minItems": 1,
          "description": "List of Creditors for a domestic payment consent."
        }
      },
      "description": "The Initiation payload is sent by the initiating party to the LFI. It is used to request movement of funds from the Debtor Account to a Creditor for one-or-more domestic payments.",
      "additionalProperties": false
    },
    "Risk": {
      "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequests.AERisk"
    }
  },
  "description": "Elements of Personal Identifiable Information for a Domestic Payment.",
  "additionalProperties": false,
  "title": "Domestic Payment PII Schema Object"
}

{
  "type": "object",
  "required": [
    "SchemeName",
    "Identification"
  ],
  "properties": {
    "SchemeName": {
      "type": "string",
      "enum": [
        "IBAN"
      ],
      "description": "Scheme name for the Debtor Account. The Debtor Account must be an IBAN."
    },
    "Identification": {
      "type": "string",
      "minLength": 1,
      "description": "The Identification of the Debtor Account."
    },
    "Name": {
      "type": "object",
      "properties": {
        "en": {
          "type": "string",
          "maxLength": 70
        },
        "ar": {
          "type": "string",
          "maxLength": 70
        }
      },
      "minProperties": 1,
      "description": "The Debtor Account, which can be provided in both English and Arabic. Omitted if not held by the TPP.",
      "additionalProperties": false
    }
  },
  "description": "Details of the Debtor Account when provided at the TPP. Omitted if not available at the TPP or the User chooses to select the Debtor Account at the LFI.",
  "additionalProperties": false
}

{
  "type": "object",
  "required": [
    "CreditorAccount"
  ],
  "properties": {
    "CreditorAgent": {
      "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequests.AECreditorAgentProperties"
    },
    "Creditor": {
      "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequests.AECreditorProperties"
    },
    "CreditorAccount": {
      "$ref": "#/components/schemas/AEBankServiceInitiationRichAuthorizationRequests.AEDomesticCreditorAccountProperties"
    },
    "ConfirmationOfPayeeResponse": {
